    /// <summary>Draws the part of a lot inside the rectangle (x0, y0)..(x1, y1) (a chunk).</summary>
    public static void drawLot(SimState state, LotContext ctx, Lot lot, int x0, int y0, int x1, int y1)
    {
        var layout = layoutLot(ctx.seed, lot);
        bool inside(int x, int y)
        {
            return (x >= x0) && (y >= y0) && (x <= x1) && (y <= y1);
        }
        for (var y = JsMath.max(y0, lot.y); y <= JsMath.min(y1, (lot.y + lot.h) - 1); y++)
        {
            for (var x = JsMath.max(x0, lot.x); x <= JsMath.min(x1, (lot.x + lot.w) - 1); x++)
            {
                var __d6 = mapToLot(lot, x, y);
                var u = __d6.u;
                var v = __d6.v;
                state.grid.ground[Js.Idx(Grids.tileIndex(state.grid, x, y))] = Grids.GROUNDS.indexOf(layout.yard(u, v));
            }
        }
        var covered = new JsSet<string>();
        layout.buildings.forEach((b, bi) => drawBuilding(state, ctx, lot, b, bi, inside, covered));
        foreach (var t in Js.Iter(layout.trees))
        {
            if (Js.T(inside(t.x, t.y)) && !covered.has($"{Js.Str(t.x)},{Js.Str(t.y)}"))
            {
                FurnitureMod.addFurniture(state, "tree", t.x, t.y);
            }
        }
        foreach (var d in Js.Iter(layout.decor))
        {
            if (Js.T(inside(d.x, d.y)) && !covered.has($"{Js.Str(d.x)},{Js.Str(d.y)}"))
            {
                FurnitureMod.addFurniture(state, "decor", d.x, d.y).look = d.look;
            }
        }
        parkCar(state, ctx, lot, inside);
    }
    public static void drawLot(SimState state, LotContext ctx, Lot lot, double x0, double y0, double x1, double y1) => drawLot(state, ctx, lot, (int)x0, (int)y0, (int)x1, (int)y1);

    /// <summary>Of the lots in town (houses, shops, civic, industry), this many have a car parked in the street in front.</summary>
    public const double CAR_CHANCE = 0.6;

    /// <summary>A car in the street in front of a lot in town, some of the time (by hash): along the street, a little fuel, some wear. Only the chunk holding its tile parks it, so it's parked once.</summary>
